#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    std::vector<int> processQueries(std::vector<int>& queries, int m) {
        std::vector<int> p(m);
        std::iota(p.begin(), p.end(), 1);
        std::vector<int> res;
        for (int q : queries) {
            auto it = std::find(p.begin(), p.end(), q);
            int idx = std::distance(p.begin(), it);
            res.push_back(idx);
            p.erase(it);
            p.insert(p.begin(), q);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] processQueries(int[] queries, int m) {
        List<Integer> p = new LinkedList<>();
        for (int i = 1; i <= m; i++) p.add(i);
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            int idx = p.indexOf(q);
            res[i] = idx;
            p.remove(idx);
            p.add(0, q);
        }
        return res;
    }
}

var processQueries = function(queries, m) {
    const p = Array.from({ length: m }, (_, i) => i + 1);
    const res = [];
    for (const q of queries) {
        const idx = p.indexOf(q);
        res.push(idx);
        p.splice(idx, 1);
        p.unshift(q);
    }
    return res;
};
